glsl3.vert:
precision highp float;
uniform CCGlobal {
  vec4 cc_time;

  vec4 cc_screenSize;

  vec4 cc_screenScale;

  vec4 cc_nativeSize;

  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;

  vec4 cc_exposure;

  vec4 cc_mainLitDir;

  vec4 cc_mainLitColor;

  vec4 cc_ambientSky;
  vec4 cc_ambientGround;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};

in vec3 a_position;
in vec4 a_color;
out vec4 v_color;

#if USE_TEXTURE
in vec2 a_uv0;
out vec2 v_uv0;
#endif

void main () {
  vec4 pos = cc_matViewProj * vec4(a_position, 1);
  gl_Position = pos;
  v_uv0 = a_uv0;
  v_color = a_color;
}

glsl3.frag:
precision highp float;

in vec4 v_color;

#if USE_TEXTURE
in vec2 v_uv0;
uniform sampler2D texture;
#endif

uniform PROPERTIES {
  vec4 color;
  float time;
};

void main () {
  float time = time * .5+5.;

  vec2 uv = v_uv0.xy;

  vec2 p = mod(uv*6.12, 6.12)-250.0;

  vec2 i = vec2(p);
  float c = 1.0;

  float inten = .02;

  for (int n = 0; n < 3 ; n++)
  {
      float t =  time * (1.0 - (3.5 / float(n+1)));
      i = p + vec2(cos(t - i.x) + sin(t + i.y), sin(t - i.y) + cos(1.5*t + i.x));
      c += 1.0/length(vec2(p.x / (cos(i.x+t)/inten),p.y / (cos(i.y+t)/inten)));
  }
  c /= float(3 );
  c = 1.17-pow(c, 1.4);
  vec4 tex = texture2D(texture,uv);

  float rate = pow(abs(c), 20.0);
  vec3 colour = vec3(0.81569, 0.44314, 0.04314) * rate * 2.0;
  colour = clamp(colour + vec3(0.0, 0.0, .0), 0.0, tex.a);

  float alpha = c*tex[3];  
  tex[0] = tex[0] + colour[0]*alpha; 
  tex[1] = tex[1] + colour[1]*alpha; 
  tex[2] = tex[2] + colour[2]*alpha; 
  vec4 o = color * tex;
  #if CC_USE_ALPHA_ATLAS_TEXTURE
    o.a *= texture2D(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  gl_FragColor = o;
}

